1	// Amplitudes for 0 -> qb- g- q+ g+ g+ from:
2	// 'One-Loop Corrections to Two-Quark Three-Gluon Amplitudes'
3	//  Zvi Bern, Lance Dixon, David A. Kosower
4	// Published in: Nucl.Phys.B 437 (1995) 259-304,
5	// e-Print: hep-ph/9409393 [hep-ph]
6	
7	#include <constants_mod.hpp>
8	#include <epinv_mod.hpp>
9	#include <epinv2_mod.hpp>
10	#include <mxpart_mod.hpp>
11	#include <scale_mod.hpp>
12	#include <sprods_com_mod.hpp>
13	#include <FArray.hpp>
14	#include <complex>
15	#include <Need.hpp>
16	
17	void A5qbmgmqpgpgp(int j1, int j2, int j3, int j4, int j5,
18	                    FArray2D<std::complex<double>>& za,
19	                    FArray2D<std::complex<double>>& zb,
20	                    std::complex<double>& miA5tree,
21	                    std::complex<double>& AL,
22	                    std::complex<double>& ASUSY,
23	                    std::complex<double>& Af,
24	                    std::complex<double>& As) {
25	
26	    using namespace constants_mod;
27	    using namespace epinv_mod;
28	    using namespace epinv2_mod;
29	    using namespace mxpart_mod;
30	    using namespace scale_mod;
31	    using namespace sprods_com_mod;
32	
33	    std::complex<double> VSUSY, VL, Vggluon, Vg13;
34	    std::complex<double> FSUSY, FS, FL, Ffgluon, Ff;
35	
36	    // Eq. (5.19)
37	    miA5tree = std::pow(za(j1,j2),3) * za(j3,j2)
38	        / (za(j1,j2) * za(j2,j3) * za(j3,j4) * za(j4,j5) * za(j5,j1));
39	
40	    Vggluon = -five*epinv*epinv2
41	        - epinv*(lnrat(musq,-s(j1,j2)) + lnrat(musq,-s(j2,j3)) + lnrat(musq,-s(j3,j4))
42	                 + lnrat(musq,-s(j4,j5)) + lnrat(musq,-s(j5,j1)))
43	        - half*(std::pow(lnrat(musq,-s(j1,j2)),2) + std::pow(lnrat(musq,-s(j2,j3)),2) + std::pow(lnrat(musq,-s(j3,j4)),2)
44	                + std::pow(lnrat(musq,-s(j4,j5)),2) + std::pow(lnrat(musq,-s(j5,j1)),2))
45	        + lnrat(-s(j1,j2),-s(j2,j3))*lnrat(-s(j3,j4),-s(j4,j5))
46	        + lnrat(-s(j2,j3),-s(j3,j4))*lnrat(-s(j4,j5),-s(j5,j1))
47	        + lnrat(-s(j3,j4),-s(j4,j5))*lnrat(-s(j5,j1),-s(j1,j2))
48	        + lnrat(-s(j4,j5),-s(j5,j1))*lnrat(-s(j1,j2),-s(j2,j3))
49	        + lnrat(-s(j5,j1),-s(j1,j2))*lnrat(-s(j2,j3),-s(j3,j4))
50	        + five/six*pisq;
51	    Vg13 = Vggluon
52	        + epinv*epinv2 + epinv*lnrat(musq,-s(j1,j2)) + half*std::pow(lnrat(musq,-s(j1,j2)),2)
53	        + epinv*epinv2 + epinv*lnrat(musq,-s(j2,j3)) + half*std::pow(lnrat(musq,-s(j2,j3)),2);
54	
55	    VSUSY = Vggluon - 3.0*epinv - 1.5*(lnrat(musq,-s(j2,j3)) + lnrat(musq,-s(j5,j1))) - 6.0;
56	    VL = Vg13 - 1.5*(epinv + lnrat(musq,-s(j2,j3))) - 3.0
57	        + Lsm1(-s(j3,j4),-s(j5,j1),-s(j2,j3),-s(j5,j1))
58	        + Lsm1(-s(j1,j2),-s(j3,j4),-s(j5,j1),-s(j3,j4));
59	
60	    // Eq. (5.20)
61	    FSUSY =
62	        1.5*za(j1,j2)*(za(j2,j3)*zb(j3,j4)*za(j4,j1) + za(j2,j4)*zb(j4,j5)*za(j5,j1))
63	        / (za(j3,j4)*za(j4,j5)*za(j5,j1))
64	        * L0(-s(j2,j3),-s(j5,j1)) / s(j5,j1);
65	
66	    Ffgluon = FSUSY*za(j1,j2)/(3.0*za(j3,j2));
67	
68	    FS = (1.0/3.0)*zb(j3,j4)*zb(j3,j5)/(zb(j1,j2)*zb(j2,j3)*za(j4,j5));
69	
70	    FL = FS
71	        + 0.5*za(j1,j5)*std::pow(zb(j5,j4),2)*std::pow(za(j4,j2),2)/(za(j3,j4)*za(j4,j5))
72	          * L1(-s(j2,j3),-s(j5,j1))/std::pow(s(j5,j1),2)
73	        + 2.0*za(j1,j2)*za(j2,j4)*zb(j4,j5)*za(j5,j1)/(za(j3,j4)*za(j4,j5)*za(j5,j1))
74	          * L0(-s(j2,j3),-s(j5,j1))/s(j5,j1)
75	        + 0.5*zb(j4,j5)*zb(j3,j5)*zb(j1,j3)/(zb(j2,j3)*zb(j1,j2)*zb(j1,j5)*za(j4,j5));
76	
77	    Ff = czip;
78	
79	    AL = VL*miA5tree + FL;
80	    ASUSY = VSUSY*miA5tree + FSUSY;
81	    // Vs = Vf =0, per Eq. (5.10)
82	    Af = Ff;
83	    As = FS;
84	
85	    return;
86	}
87	
88	extern "C" {
89	    void A5qbmgmqpgpgp_wrapper(int j1, int j2, int j3, int j4, int j5,
90	                                std::complex<double>* za, std::complex<double>* zb,
91	                                std::complex<double>* miA5tree,
92	                                std::complex<double>* AL, std::complex<double>* ASUSY,
93	                                std::complex<double>* Af, std::complex<double>* As) {
94	
95	        using namespace mxpart_mod;
96	
97	        FArray2D<std::complex<double>> za_array(za, mxpart, mxpart);
98	        FArray2D<std::complex<double>> zb_array(zb, mxpart, mxpart);
99	
100	        A5qbmgmqpgpgp(j1, j2, j3, j4, j5, za_array, zb_array,
101	                      *miA5tree, *AL, *ASUSY, *Af, *As);
102	    }
103	}
