#include <blha_mod.hpp>
#include <cmath>
#include <complex>
#include <constants_mod.hpp>
#include <epinv_mod.hpp>
#include <ewcharge_mod.hpp>
#include <masses_mod.hpp>
#include <mxpart_mod.hpp>
#include <nf_mod.hpp>
#include <nflav_mod.hpp>
#include <qcdcouple_mod.hpp>
#include <scheme_mod.hpp>
#include <sprods_com_mod.hpp>
#include <virt5ax_mod.hpp>
#include <zcouple_cms_mod.hpp>
#include <zcouple_mod.hpp>
#include <zprods_com_mod.hpp>
#include <FArray.hpp>
#include <Need.hpp>
#include <Z1jet.hpp>
#include <W1jet.hpp>
#include <cstring>

using namespace constants_mod;
using namespace nf_mod;
using namespace mxpart_mod;
using namespace masses_mod;
using namespace qcdcouple_mod;
using namespace ewcharge_mod;
using namespace zcouple_mod;
using namespace sprods_com_mod;
using namespace zprods_com_mod;
using namespace epinv_mod;
using namespace scheme_mod;
using namespace nflav_mod;
using namespace zcouple_cms_mod;
using namespace virt5ax_mod;
using namespace blha_mod;

void qqb_z1jet_v_main(FArray2D<double>& p, FArray2D<double>& msq) {
    int j, k;
    double fac, sz, subuv;
    std::complex<double> zsin2winv, prop;
    FArray2D<double> msq0(2*nf+1, 2*nf+1, -nf, -nf);
    FArray1D<std::complex<double>> cLL(nf), cLR(nf), cRL(nf), cRR(nf);
    FArray1D<std::complex<double>> qqbZgLL(2), qqbZgRR(2), qqbZgLR(2), qqbZgRL(2);
    FArray1D<std::complex<double>> gqZqLL(2), gqZqRR(2), gqZqLR(2), gqZqRL(2);
    FArray1D<std::complex<double>> qgZqLL(2), qgZqRR(2), qgZqLR(2), qgZqRL(2);
    FArray1D<std::complex<double>> qbqZgLL(2), qbqZgRR(2), qbqZgLR(2), qbqZgRL(2);
    FArray1D<std::complex<double>> gqbZqbLL(2), gqbZqbRR(2), gqbZqbLR(2), gqbZqbRL(2);
    FArray1D<std::complex<double>> qbgZqbLL(2), qbgZqbRR(2), qbgZqbLR(2), qbgZqbRL(2);

    const bool includeanom = true;
    FArray1D<int> iqqbgLL({1, 2, 3, 4, 5}, 5);
    FArray1D<int> iqqbgLR({1, 2, 4, 3, 5},5);
    FArray1D<int> iqgqLL({1, 5, 3, 4, 2},5);
    FArray1D<int> iqgqLR({1, 5, 4, 3, 2},5);
    FArray1D<int> igqqLL({2, 5, 3, 4, 1},5);
    FArray1D<int> igqqLR({2, 5, 4, 3, 1},5);

    std::strcpy(scheme, "dred");
    msq.fill(0.0);

    spinoru(5,p,za,zb);
    qqb_z1jet_main(p,msq0);

    subuv = ason2pi * xn * (epinv * (11.0 - 2.0 * std::real(nflav) / xn) - 1.0) / 6.0;

    sz = s(3, 4);
    prop = sz / cplx2(sz - zmass * zmass, zmass * zwidth);

    fac = 8.0 * cf * xnsq * std::abs(zesq) * std::abs(zesq) * gsq;

    qqbZgLL(1)=aveqq*fac*cplx1(virt5(iqqbgLL,za,zb));
    qqbZgLL(2)=-aveqq*fac*virt5ax;
    qqbZgLR(1)=aveqq*fac*cplx1(virt5(iqqbgLR,za,zb));
    qqbZgLR(2)=-aveqq*fac*virt5ax;
    qqbZgRL(1)=aveqq*fac*cplx1(virt5(iqqbgLR,zb,za));
    qqbZgRL(2)=aveqq*fac*virt5ax;
    qqbZgRR(1)=aveqq*fac*cplx1(virt5(iqqbgLL,zb,za));
    qqbZgRR(2)=aveqq*fac*virt5ax;


    for (int i=1; i<=2; i++) {
      qbqZgLL(i) = qqbZgRL(i);
      qbqZgLR(i) = qqbZgRR(i);
      qbqZgRL(i) = qqbZgLL(i);
      qbqZgRR(i) = qqbZgLR(i);
    }

    if (useblha == 0) {
      gqZqLL(1)=aveqg*fac*cplx1(virt5(igqqLL,za,zb));
      gqZqLL(2)=-aveqg*fac*virt5ax;
      gqZqLR(1)=aveqg*fac*cplx1(virt5(igqqLR,za,zb));
      gqZqLR(2)=-aveqg*fac*virt5ax;
      gqZqRL(1)=aveqg*fac*cplx1(virt5(igqqLR,zb,za));
      gqZqRL(2)=aveqg*fac*virt5ax;
      gqZqRR(1)=aveqg*fac*cplx1(virt5(igqqLL,zb,za));
      gqZqRR(2)=aveqg*fac*virt5ax;
    }

    for (int i=1; i<=2; i++) {
      gqbZqbRL(i) = gqZqLL(i);
      gqbZqbRR(i) = gqZqLR(i);
      gqbZqbLL(i) = gqZqRL(i);
      gqbZqbLR(i) = gqZqRR(i);
    }

    if (useblha == 0) {
        qgZqLL(1)=aveqg*fac*cplx1(virt5(iqgqLL,za,zb));
        qgZqLL(2)=-aveqg*fac*virt5ax;
        qgZqLR(1)=aveqg*fac*cplx1(virt5(iqgqLR,za,zb));
        qgZqLR(2)=-aveqg*fac*virt5ax;
        qgZqRL(1)=aveqg*fac*cplx1(virt5(iqgqLR,zb,za));
        qgZqRL(2)=aveqg*fac*virt5ax;
        qgZqRR(1)=aveqg*fac*cplx1(virt5(iqgqLL,zb,za));
        qgZqRR(2)=aveqg*fac*virt5ax;
    }

    for (int i=1; i<=2; i++) {
      qbgZqbRL(i) = qgZqLL(i);
      qbgZqbRR(i) = qgZqLR(i);
      qbgZqbLL(i) = qgZqRL(i);
      qbgZqbLR(i) = qgZqRR(i);
    }

    zsin2winv = zl(2) - zr(2);
    for (j=1; j<=nf; j++) {
      cLL(j)=Q(j)*q1+zl(j)*zl1*prop;
      cRR(j)=Q(j)*q1+zr(j)*zr1*prop;
      cLR(j)=Q(j)*q1+zl(j)*zr1*prop;
      cRL(j)=Q(j)*q1+zr(j)*zl1*prop;
    }

    for (j = -nflav; j <= nflav; j++) {
        for (k = -nflav; k <= nflav; k++) {
            if (j != 0 && k != 0 && j != -k) {
            } else {
            if (j == 0 && k == 0) {
                msq(j, k) = 0.0;
            } else if (j > 0 && k < 0) {
                msq(j, k) = +std::real(cLL(j) * std::conj(cLL(j)) * qqbZgLL(1))
                            + std::real(cRR(j) * std::conj(cRR(j)) * qqbZgRR(1))
                            + std::real(cLR(j) * std::conj(cLR(j)) * qqbZgLR(1))
                            + std::real(cRL(j) * std::conj(cRL(j)) * qqbZgRL(1))
                            - subuv * msq0(j, k);
                if (includeanom) {
                    msq(j, k) = msq(j, k)
                                + std::real(zsin2winv * zl1 * prop * (qqbZgLL(2) * std::conj(cLL(j)) + qqbZgRL(2) * std::conj(cRL(j))))
                                + std::real(zsin2winv * zr1 * prop * (qqbZgRR(2) * std::conj(cRR(j)) + qqbZgLR(2) * std::conj(cLR(j))));
                }
            } else if (j < 0 && k > 0) {
                msq(j, k) = +std::real(cLL(k) * std::conj(cLL(k)) * qbqZgLL(1))
                            + std::real(cRR(k) * std::conj(cRR(k)) * qbqZgRR(1))
                            + std::real(cLR(k) * std::conj(cLR(k)) * qbqZgLR(1))
                            + std::real(cRL(k) * std::conj(cRL(k)) * qbqZgRL(1))
                            - subuv * msq0(j,k); // Adjust index for msq0 if needed
                if (includeanom) {
                    msq(j, k) = msq(j, k)
                                + std::real(zsin2winv * zl1 * prop * (qbqZgLL(2) * std::conj(cLL(k)) + qbqZgRL(2) * std::conj(cRL(k))))
                                + std::real(zsin2winv * zr1 * prop * (qbqZgRR(2) * std::conj(cRR(k)) + qbqZgLR(2) * std::conj(cLR(k))));
                }
            } else if (j > 0 && k == 0) {
                msq(j, k) = +std::real(cLL(j) * std::conj(cLL(j)) * qgZqLL(1))
                            + std::real(cRR(j) * std::conj(cRR(j)) * qgZqRR(1))
                            + std::real(cLR(j) * std::conj(cLR(j)) * qgZqLR(1))
                            + std::real(cRL(j) * std::conj(cRL(j)) * qgZqRL(1))
                            - subuv * msq0(j,k); // Adjust index for msq0 if needed
                if (includeanom) {
                    msq(j, k) = msq(j, k)
                                + std::real(zsin2winv * zl1 * prop * (qgZqLL(2) * std::conj(cLL(j)) + qgZqRL(2) * std::conj(cRL(j))))
                                + std::real(zsin2winv * zr1 * prop * (qgZqRR(2) * std::conj(cRR(j)) + qgZqLR(2) * std::conj(cLR(j))));
                }
            } else if (j < 0 && k == 0) {
                msq(j, k) = +std::real(cLL(-j) * std::conj(cLL(-j)) * qbgZqbLL(1))
                            + std::real(cRR(-j) * std::conj(cRR(-j)) * qbgZqbRR(1))
                            + std::real(cLR(-j) * std::conj(cLR(-j)) * qbgZqbLR(1))
                            + std::real(cRL(-j) * std::conj(cRL(-j)) * qbgZqbRL(1))
                            - subuv * msq0(j,k); // Adjust index for msq0 if needed
                if (includeanom) {
                    msq(j, k) = msq(j, k)
                                + std::real(zsin2winv * zl1 * prop * (qbgZqbLL(2) * std::conj(cLL(-j)) + qbgZqbRL(2) * std::conj(cRL(-j))))
                                + std::real(zsin2winv * zr1 * prop * (qbgZqbRR(2) * std::conj(cRR(-j)) + qbgZqbLR(2) * std::conj(cLR(-j))));
                }
            } else if (j == 0 && k > 0) {
                msq(j, k) = +std::real(cLL(k) * std::conj(cLL(k)) * gqZqLL(1))
                            + std::real(cRR(k) * std::conj(cRR(k)) * gqZqRR(1))
                            + std::real(cLR(k) * std::conj(cLR(k)) * gqZqLR(1))
                            + std::real(cRL(k) * std::conj(cRL(k)) * gqZqRL(1))
                            - subuv * msq0(j,k); // Adjust index for msq0 if needed
                if (includeanom) {
                    msq(j, k) = msq(j, k)
                                + std::real(zsin2winv * zl1 * prop * (gqZqLL(2) * std::conj(cLL(k)) + gqZqRL(2) * std::conj(cRL(k))))
                                + std::real(zsin2winv * zr1 * prop * (gqZqRR(2) * std::conj(cRR(k)) + gqZqLR(2) * std::conj(cLR(k))));
                }
            } else if (j == 0 && k < 0) {
                msq(j, k) = +std::real(cLL(-k) * std::conj(cLL(-k)) * gqbZqbLL(1))
                            + std::real(cRR(-k) * std::conj(cRR(-k)) * gqbZqbRR(1))
                            + std::real(cLR(-k) * std::conj(cLR(-k)) * gqbZqbLR(1))
                            + std::real(cRL(-k) * std::conj(cRL(-k)) * gqbZqbRL(1))
                            - subuv * msq0(j,k); // Adjust index for msq0 if needed
                if (includeanom) {
                    msq(j, k) = msq(j, k)
                                + std::real(zsin2winv * zl1 * prop * (gqbZqbLL(2) * std::conj(cLL(-k)) + gqbZqbRL(2) * std::conj(cRL(-k))))
                                + std::real(zsin2winv * zr1 * prop * (gqbZqbRR(2) * std::conj(cRR(-k)) + gqbZqbLR(2) * std::conj(cLR(-k))));
                }
            }
          }
        }
    }
}

void qqb_z1jet_v_wrapper(double* fp, double* fmsq) {
    FArray2D<double> p(fp, mxpart, 4);
    FArray2D<double> msq(fmsq, 2*nf+1, 2*nf+1, -nf, -nf);
    qqb_z1jet_v_main(p, msq);
}

