  using namespace scheme_mod;
  using namespace nflav_mod;

  int j, k;
  FArray2D<double> msq0(2*nf+1, 2*nf+1, -nf, -nf);
  double fac, sw, prop, subuv;
  double qqbWg, qbqWg, qgWq, gqWq, qbgWqb, gqbWqb;

  FArray1D<int> iqqbg({1, 2, 3, 4, 5},5);
  FArray1D<int> iqgq({1, 5, 3, 4, 2},5);
  FArray1D<int> igqq({2, 5, 3, 4, 1},5);
  FArray1D<int> iqbqg({2, 1, 3, 4, 5},5);
  FArray1D<int> iqbgqb({5, 1, 3, 4, 2},5);
  FArray1D<int> igqbqb({5, 2, 3, 4, 1},5);

  msq.fill(zip);
  std::strcpy(scheme,"dred");

  spinoru(5,p,za,zb);
  qqb_w_g_main(p,msq0);

  subuv = ason2pi * xn * (epinv * (eleven - two * std::real(nflav) / xn) - one) / six;

  sw = s(3, 4);  // Assuming s is defined elsewhere
  prop = std::pow(sw, 2) / ((sw - std::pow(wmass, 2)) * (sw - std::pow(wmass, 2)) + (wmass * wwidth) * (wmass * wwidth));

  fac = two * cf * xnsq * std::pow(gwsq, 2) * gsq * prop;

  if ((useblha == 0) || (blhatype == 1)) {
    qqbWg = aveqq * fac * virt5(iqqbg, za, zb);  // Assuming virt5 is defined elsewhere
  }
  if (useblha == 0) {
    qbqWg = aveqq * fac * virt5(iqbqg, za, zb);
  }
  if ((useblha == 0) || (blhatype == 2)) {
    gqWq = aveqg * fac * virt5(igqq, za, zb);

  }
  if ((useblha == 0) || (blhatype == 2)) {
    gqWq = aveqg * fac * virt5(igqq, za, zb);
  }
  if (useblha == 0) {
    qgWq = aveqg * fac * virt5(iqgq, za, zb);
    gqbWqb = aveqg * fac * virt5(igqbqb, za, zb);
    qbgWqb = aveqg * fac * virt5(iqbgqb, za, zb);
  }

  for (j = -nf; j <= nf; j++) {
    for (k = -nf; k <= nf; k++) {
      if ((j > 0) && (k < 0)) {
        msq(j, k) = Vsq(j, k) * qqbWg - subuv * msq0(j, k);
      } else if ((j < 0) && (k > 0)) {
        msq(j, k) = Vsq(j, k) * qbqWg - subuv * msq0(j, k);
      } else if ((j > 0) && (k == 0)) {
        msq(j, k) = (Vsq(j, -1) + Vsq(j, -2) + Vsq(j, -3) + Vsq(j, -4) + Vsq(j, -5)) * qgWq - subuv * msq0(j, k);
