      } else if ((j == 0) && (k < 0)) {
        msq(j, k) = (Vsq(+1, k) + Vsq(+2, k) + Vsq(+3, k) + Vsq(+4, k) + Vsq(+5, k)) * gqbWqb - subuv * msq0(j, k);
      }
    }
  }

  return;
}

