// Author: J. Campbell, September 2014
// Virtual matrix elements for three-jet production

#include <blha_mod.hpp>
#include <constants_mod.hpp>
#include <cstring>
#include <mxpart_mod.hpp>
#include <nf_mod.hpp>
#include <nflav_mod.hpp>
#include <qcdcouple_mod.hpp>
#include <scheme_mod.hpp>
#include <zprods_com_mod.hpp>
#include <FArray.hpp>
#include <Need.hpp>

using namespace constants_mod;
using namespace nf_mod;
using namespace mxpart_mod;
using namespace nflav_mod;
using namespace qcdcouple_mod;
using namespace zprods_com_mod;
using namespace scheme_mod;
using namespace blha_mod;

// A5NLOggggg, A5NLOqbqggg and A5NLO4qg are still Fortran (ThreeJets/A5NLOggggg.f,
// ThreeJets/A5NLOqbqggg.f, ThreeJets/A5NLO4qg.f); call them by their plain Fortran
// symbol names with pointer arguments.
extern "C" {
  double a5nloggggg_();
  double a5nloqbqggg_(int* j1, int* j2, int* j3, int* j4, int* j5);
  double a5nlo4qg_(int* j1, int* j2, int* j3, int* j4, int* j5, int* identical);
}

void qqb_thrjet_v(FArray2D<double>& p, FArray2D<double>& msq) {
  int j, k;
  double fac;
  double gg, qqb, qbq, qg, qbg, gq, gqb, qrqr, qqqq;

  int i1 = 1, i2 = 2, i3 = 3, i4 = 4, i5 = 5;
  int ifalse = 0, itrue = 1;

  std::strcpy(scheme, "tH-V");
  msq.fill(zip);

  spinoru(5, p, za, zb);

  // gg -> ggg
  if (useblha == 0 || (blhatype == 1)) {
    gg = a5nloggggg_() / 6.0;
  } else {
    gg = zip;
  }

  // gg -> qbqg
  if (useblha == 0) {
    gg = gg + static_cast<double>(nflav) * a5nloqbqggg_(&i3, &i4, &i1, &i2, &i5);
  }
  // qqb -> ggg
  if (useblha == 0 || (blhatype == 2)) {
    qqb = a5nloqbqggg_(&i1, &i2, &i3, &i4, &i5) / 6.0;
  } else {
    qqb = zip;
  }
  // qbq -> ggg
  if (useblha == 0) {
    qbq = a5nloqbqggg_(&i2, &i1, &i3, &i4, &i5) / 6.0;
  } else {
    qbq = zip;
  }
  // qg -> ggq
  if (useblha == 0) {
    qg = a5nloqbqggg_(&i1, &i5, &i3, &i4, &i2) / 2.0;
  } else {
    qg = zip;
  }
  // gqb -> ggqb
  if (useblha == 0) {
    gqb = a5nloqbqggg_(&i5, &i2, &i3, &i4, &i1) / 2.0;
  } else {
    gqb = zip;
  }
  // gq -> ggq
  if (useblha == 0) {
    gq = a5nloqbqggg_(&i2, &i5, &i3, &i4, &i1) / 2.0;
  } else {
    gq = zip;
  }
  // qbg -> ggqb
  if (useblha == 0) {
    qbg = a5nloqbqggg_(&i5, &i1, &i3, &i4, &i2) / 2.0;
  } else {
    qbg = zip;
  }

  // This 4-quark section should be extended if we really want to compute
  // all 4-quark contributions (not just relevant ones for the interface)
  // q r -> q r g
  if ((useblha == 0) || (blhatype == 4)) {
    qrqr = a5nlo4qg_(&i1, &i2, &i3, &i4, &i5, &ifalse);
  }
  if ((useblha == 0) || (blhatype == 3)) {
    qqqq = a5nlo4qg_(&i1, &i2, &i3, &i4, &i5, &itrue);
  }

  // fill array, including initial state averaging
  msq(0, 0) = avegg * gg; // @coverage-probe
  for (j = 1; j <= nf; j++) {
    msq(j, -j) = aveqq * qqb;
    msq(-j, j) = aveqq * qbq;
    msq(j, 0) = aveqg * qg;
    msq(-j, 0) = aveqg * qbg;
    msq(0, j) = aveqg * gq;
    msq(0, -j) = aveqg * gqb;
  }

  for (j = 1; j <= nf; j++) {
    for (k = 1; k <= nf; k++) {
      if (j == k) {
        msq(j, k) = aveqq * qqqq;
      } else {
        msq(j, k) = aveqq * qrqr;
      }
    }
  }

  return;
}

extern "C" {
  void qqb_thrjet_v_wrapper(double* fp, double* fmsq) {
    FArray2D<double> p(fp, mxpart, 4);
    FArray2D<double> msq(fmsq, 2 * nf + 1, 2 * nf + 1, -nf, -nf);
    qqb_thrjet_v(p, msq);
  }
}

