83	    gqb = a5nloqbqggg_(&i5, &i2, &i3, &i4, &i1) / 2.0;
84	  } else {
85	    gqb = zip;
86	  }
87	  // gq -> ggq
88	  if (useblha == 0) {
89	    gq = a5nloqbqggg_(&i2, &i5, &i3, &i4, &i1) / 2.0;
90	  } else {
91	    gq = zip;
92	  }
93	  // qbg -> ggqb
94	  if (useblha == 0) {
95	    qbg = a5nloqbqggg_(&i5, &i1, &i3, &i4, &i2) / 2.0;
96	  } else {
97	    qbg = zip;
98	  }
99	
100	  // This 4-quark section should be extended if we really want to compute
101	  // all 4-quark contributions (not just relevant ones for the interface)
102	  // q r -> q r g
103	  if ((useblha == 0) || (blhatype == 4)) {
104	    qrqr = a5nlo4qg_(&i1, &i2, &i3, &i4, &i5, &ifalse);
105	  }
106	  if ((useblha == 0) || (blhatype == 3)) {
107	    qqqq = a5nlo4qg_(&i1, &i2, &i3, &i4, &i5, &itrue);
108	  }
109	
110	  // fill array, including initial state averaging
111	  msq(0, 0) = avegg * gg; // @coverage-probe
112	  for (j = 1; j <= nf; j++) {
113	    msq(j, -j) = aveqq * qqb;
114	    msq(-j, j) = aveqq * qbq;
115	    msq(j, 0) = aveqg * qg;
116	    msq(-j, 0) = aveqg * qbg;
117	    msq(0, j) = aveqg * gq;
118	    msq(0, -j) = aveqg * gqb;
119	  }
120	
121	  for (j = 1; j <= nf; j++) {
122	    for (k = 1; k <= nf; k++) {
123	      if (j == k) {
124	        msq(j, k) = aveqq * qqqq;
125	      } else {
126	        msq(j, k) = aveqq * qrqr;
127	      }
128	    }
129	  }
130	
131	  return;
132	}
