135	  void qqb_thrjet_v_wrapper(double* fp, double* fmsq) {
136	    FArray2D<double> p(fp, mxpart, 4);
137	    FArray2D<double> msq(fmsq, 2 * nf + 1, 2 * nf + 1, -nf, -nf);
138	    qqb_thrjet_v(p, msq);
139	  }
